import structimport mathfilepath=r'C:\Users\michael.cheng\OneDrive - ANSYS, Inc\temp\MCheng16_desktop\Document_backup\Zemax\Objects\Sources\Source Files\SFT-10-CG_100000Rays_ZEMAX.dat'bfile=open(filepath, 'rb')Identifier = int.from_bytes(bfile.read(4), byteorder='little')NbrRays = int.from_bytes(bfile.read(4), byteorder='little')Description = bfile.read(100).decode()SourceFlux = struct.unpack('f', bfile.read(4))[0]RaySetFlux = struct.unpack('f', bfile.read(4))[0]Wavelength = struct.unpack('f', bfile.read(4))[0]InclinationBeg = struct.unpack('f', bfile.read(4))[0]InclinationEnd = struct.unpack('f', bfile.read(4))[0]AzimuthBeg = struct.unpack('f', bfile.read(4))[0]AzimuthEnd = struct.unpack('f', bfile.read(4))[0]DimensionUnits = int.from_bytes(bfile.read(4), byteorder='little')LocX = struct.unpack('f', bfile.read(4))[0]LocY = struct.unpack('f', bfile.read(4))[0]LocZ = struct.unpack('f', bfile.read(4))[0]RotX = struct.unpack('f', bfile.read(4))[0]RotY = struct.unpack('f', bfile.read(4))[0]RotZ = struct.unpack('f', bfile.read(4))[0]ScaleX = struct.unpack('f', bfile.read(4))[0]ScaleY = struct.unpack('f', bfile.read(4))[0]ScaleZ = struct.unpack('f', bfile.read(4))[0]bfile.read(4*4)ray_format_type = int.from_bytes(bfile.read(4), byteorder='little')flux_type = int.from_bytes(bfile.read(4), byteorder='little')bfile.read(4*2)print('Identifier =       ' + str(Identifier))print('NbrRays =          ' + str(NbrRays))print('Description =      ' + str(Description))print('SourceFlux =       ' + str(SourceFlux))print('RaySetFlux =       ' + str(RaySetFlux))print('Wavelength =       ' + str(Wavelength))print('DimensionUnits =   ' + str(DimensionUnits))print('ray_format_type =  ' + str(ray_format_type))print('flux_type =        ' + str(flux_type))print('=======================')if ray_format_type != 0 and ray_format_type != 2:    print('ray_format_type is in wrong format')    exit()Numer_Of_Rays_to_Show = 30for m in range(1, Numer_Of_Rays_to_Show + 1,1):    print('Ray #' + str(m) + ':')    print('x = \t' + str(struct.unpack('f', bfile.read(4))[0]))    print('y = \t' + str(struct.unpack('f', bfile.read(4))[0]))    print('z = \t' + str(struct.unpack('f', bfile.read(4))[0]))    l = struct.unpack('f', bfile.read(4))[0]    m = struct.unpack('f', bfile.read(4))[0]    n = struct.unpack('f', bfile.read(4))[0]    print('l = \t' + str(l))    print('m = \t' + str(m))    print('n = \t' + str(n))    print('flux (Watts) =     ' + str(struct.unpack('f', bfile.read(4))[0]))    if ray_format_type == 2:        print('wavelength (um) =  ' + str(struct.unpack('f', bfile.read(4))[0]))    print('Data Check: sqrt(l^2+m^2+n^2)-1 = ' + str(math.sqrt(l**2+m**2+n**2)-1))    print('===========')